package mod.cdv.tnpc.tactical;
import fixture.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.item.ItemStack;import mod.cdv.tnpc.entity.AutoGunOperator;
public class Conversation19Checks{
 static int checks;static void ok(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}static int act(World w,Player p,String a){w.now+=20;return Conversation.action(p,a);}
 public static void main(String[] args)throws Exception{World w=new World();AutoGunOperator n=new AutoGunOperator(w);Player p=new Player(w);p.x=2;Social.init(n);n.tag.putInt("soc_kind",1);n.tag.putInt("soc_persona",2);Conversation.interact(n,p,net.minecraft.world.InteractionHand.MAIN_HAND);
 ok(act(w,p,"favor_ask")==1&&TalkNetwork.last.contains("need_food"),"NPC asks for a specific supply");p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("minecraft:coal",2));ok(act(w,p,"favor_give")==0&&p.getMainHandItem().count==2,"wrong supply never consumed");p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("minecraft:bread",3));ok(act(w,p,"favor_give")==1&&p.getMainHandItem().count==2&&n.bag.get(0).id.equals("minecraft:bread"),"one requested item moves into actual NPC bag");ok(Social.trust(n,p)==12&&Social.rep(p)==2,"completed favor changes trust and reputation");ok(act(w,p,"favor_give")==0&&p.getMainHandItem().count==2,"completed favor cannot be repeated without request");act(w,p,"favor_ask");ok(act(w,p,"favor_give")==0&&p.getMainHandItem().count==2,"reward cooldown prevents farming");ok(act(w,p,"favor_clean")==0,"stranger cannot demand work below trust threshold");Social.trust(n,p,5);ok(act(w,p,"favor_clean")==1&&n.tag.getLong("soc_clean_favor")==w.now+2400,"trusted stranger accepts two minute clean-up favor");
 n.hp=5;act(w,p,"favor_ask");ok(TalkNetwork.last.contains("need_medicine"),"wounded NPC asks for medical supply");int oldTrust=Social.trust(n,p);ok(act(w,p,"insult")==1&&Social.trust(n,p)==oldTrust-12,"insult harms relationship");ok(act(w,p,"insult")==0&&Social.trust(n,p)==oldTrust-12,"rude-action spam cooldown");w.now+=200;oldTrust=Social.trust(n,p);ok(act(w,p,"threaten")==1&&Social.trust(n,p)==oldTrust-20,"threat has stronger relationship penalty");p.x=99;ok(act(w,p,"favor_give")==0,"favors reject remote calls");System.out.println("NPC_SIMPLE_DIALOGUE_FAVOR_CHECKS="+checks);}
}
